const EXTRA_QUESTIONS_V17=[{"id":"AMP001","lote":5,"pagina":1,"eneatipo":1,"subtipo":"general","pregunta":"Un grupo ha organizado un viaje con horarios y reservas cerradas. La primera mañana alguien propone improvisar y saltarse medio plan. ¿Qué es más probable que irrite especialmente al Perfeccionista?","opciones":{"A":"Que se esté desmontando algo acordado y bien organizado sin una razón suficientemente buena.","B":"Que el cambio pueda generar problemas que nadie haya previsto todavía.","C":"Que seguir el plan signifique perder una oportunidad más divertida."},"correcta":"A","source_id":"AMPLIACION-20260815-001","modo":"personaje"},{"id":"AMP002","lote":5,"pagina":2,"eneatipo":1,"subtipo":"general","pregunta":"Un amigo le dice al Perfeccionista: «No hace falta que señales cada cosa que podría hacerse mejor». ¿Qué hay probablemente detrás de esa tendencia?","opciones":{"A":"La necesidad de demostrar que sabe más que los demás.","B":"La dificultad para ignorar algo que considera incorrecto cuando ve una forma clara de mejorarlo.","C":"La preocupación de que, si no interviene, acabarán culpándole del resultado."},"correcta":"B","source_id":"AMPLIACION-20260815-002","modo":"personaje"},{"id":"AMP003","lote":5,"pagina":3,"eneatipo":1,"subtipo":"general","pregunta":"El jefe pide al Perfeccionista que presente unos datos de manera deliberadamente engañosa porque «todos lo hacen». ¿Qué respuesta encaja mejor con su patrón?","opciones":{"A":"Aceptar si sirve para proteger la imagen del equipo y conseguir el objetivo.","B":"Pedir tiempo para estudiar exactamente qué consecuencias puede tener negarse.","C":"Resistirse aunque hacerlo le complique la vida, porque participar le haría sentir que está haciendo algo incorrecto."},"correcta":"C","source_id":"AMPLIACION-20260815-003","modo":"personaje"},{"id":"AMP004","lote":5,"pagina":4,"eneatipo":1,"subtipo":"general","pregunta":"El Perfeccionista tiene por delante un domingo completamente libre, pero sabe que quedan varias tareas domésticas pendientes. ¿Qué contradicción puede aparecer?","opciones":{"A":"Quiere descansar, pero una parte de él siente que debería «merecer» el descanso terminando antes lo pendiente.","B":"Quiere descansar, pero teme que alguien pueda necesitarlo y no esté disponible.","C":"Quiere descansar, pero empieza a imaginar todos los planes interesantes que podría estar perdiéndose."},"correcta":"A","source_id":"AMPLIACION-20260815-004","modo":"personaje"},{"id":"AMP005","lote":5,"pagina":5,"eneatipo":1,"subtipo":"general","pregunta":"En una comida familiar existe una norma que todos conocen. Un hermano se la salta y nadie resulta perjudicado. ¿Qué podría molestar especialmente al Perfeccionista?","opciones":{"A":"Que el hermano haya conseguido salirse con la suya y ganar protagonismo.","B":"Que se normalice hacer mal algo simplemente porque esta vez no haya tenido consecuencias.","C":"Que la familia no se pregunte qué otras normas podrían romperse en el futuro."},"correcta":"B","source_id":"AMPLIACION-20260815-005","modo":"personaje"},{"id":"AMP006","lote":5,"pagina":6,"eneatipo":1,"subtipo":"general","pregunta":"El Perfeccionista envía un informe importante y cinco minutos después descubre una errata minúscula que probablemente nadie notará. ¿Qué reacción es más característica?","opciones":{"A":"Preocuparse principalmente por que el error pueda hacerle parecer menos competente.","B":"Preguntarse si el jefe utilizará el fallo en su contra más adelante.","C":"Sentir una fuerte necesidad de corregirlo porque saber que el error sigue ahí ya le incomoda."},"correcta":"C","source_id":"AMPLIACION-20260815-006","modo":"personaje"},{"id":"AMP007","lote":5,"pagina":7,"eneatipo":1,"subtipo":"general","pregunta":"Una amiga pregunta al Perfeccionista si le queda bien un traje justo antes de una boda. Él cree sinceramente que hay otra opción mucho mejor. ¿Qué tenderá a hacer?","opciones":{"A":"Buscar una forma de decírselo con tacto en vez de tranquilizarla con algo que considera falso.","B":"Decir que está estupenda para que disfrute y no crear inseguridad innecesaria.","C":"Preguntarle qué respuesta necesita escuchar antes de opinar."},"correcta":"A","source_id":"AMPLIACION-20260815-007","modo":"personaje"},{"id":"AMP008","lote":5,"pagina":8,"eneatipo":1,"subtipo":"general","pregunta":"Una empresa tiene una norma absurda que hace perder tiempo a todo el mundo. ¿Qué diferencia mejor al Perfeccionista de alguien que simplemente odia las reglas?","opciones":{"A":"Se la saltará sin pensarlo siempre que nadie pueda descubrirlo.","B":"Puede cumplirla mientras intenta cambiarla por una vía que considere legítima.","C":"La obedecerá sobre todo porque cualquier autoridad le genera seguridad."},"correcta":"B","source_id":"AMPLIACION-20260815-008","modo":"personaje"},{"id":"AMP009","lote":5,"pagina":9,"eneatipo":1,"subtipo":"general","pregunta":"El Perfeccionista gana un concurso porque su rival ha sido eliminado por una tecnicidad que no afectaba realmente a la calidad del trabajo. ¿Qué puede ocurrirle?","opciones":{"A":"Disfrutar especialmente porque al final lo importante es que conste oficialmente como ganador.","B":"Sentirse aliviado porque así evita tener que compararse directamente con su rival.","C":"Quedarse incómodo con una victoria que no siente completamente merecida."},"correcta":"C","source_id":"AMPLIACION-20260815-009","modo":"personaje"},{"id":"AMP010","lote":5,"pagina":10,"eneatipo":1,"subtipo":"general","pregunta":"Después de meses de trabajo, un proyecto del Perfeccionista sale extraordinariamente bien salvo por un detalle que quedó peor de lo previsto. Esa noche, ¿dónde puede irse su atención?","opciones":{"A":"Al fallo concreto y a cómo podría haberse evitado, incluso mientras los demás celebran el resultado.","B":"A comprobar cuánta gente ha reconocido públicamente su aportación.","C":"A pensar en un proyecto nuevo porque este ya ha perdido toda la emoción."},"correcta":"A","source_id":"AMPLIACION-20260815-010","modo":"personaje"},{"id":"AMP011","lote":5,"pagina":11,"eneatipo":1,"subtipo":"general","pregunta":"La familia encarga al Perfeccionista organizar una celebración. Todos dicen que ayudarán, pero después cumplen las tareas a medias. ¿Qué dinámica es bastante probable?","opciones":{"A":"Dejarlo todo como está para no convertirse en quien manda sobre los demás.","B":"Terminar corrigiendo o rehaciendo cosas él mismo y acumular irritación porque los demás podrían haberlas hecho bien.","C":"Cancelar partes de la celebración para conservar tiempo y energía."},"correcta":"B","source_id":"AMPLIACION-20260815-011","modo":"personaje"},{"id":"AMP012","lote":5,"pagina":12,"eneatipo":1,"subtipo":"general","pregunta":"En el aeropuerto alguien se cuela descaradamente en una cola larguísima. ¿Qué distingue mejor la irritación del Perfeccionista?","opciones":{"A":"Le molesta sobre todo que esa persona se esté colocando por encima del resto y desafiando su autoridad.","B":"Le preocupa que el incidente pueda terminar provocando una pelea.","C":"Le enfada que una regla básica de convivencia se incumpla mientras los demás hacen correctamente su parte."},"correcta":"C","source_id":"AMPLIACION-20260815-012","modo":"personaje"},{"id":"AMP013","lote":5,"pagina":13,"eneatipo":1,"subtipo":"general","pregunta":"El Perfeccionista descubre que una decisión suya ha perjudicado a otra persona aunque lo hizo con buena intención. ¿Qué puede resultarle especialmente difícil?","opciones":{"A":"Aceptar que él mismo ha sido quien se ha equivocado y reparar el daño sin justificarse.","B":"Pensar que esa persona quizá ya no vuelva a necesitarlo.","C":"Imaginar cómo afectará el error a la reputación que tiene ante los demás."},"correcta":"A","source_id":"AMPLIACION-20260815-013","modo":"personaje"},{"id":"AMP014","lote":5,"pagina":14,"eneatipo":1,"subtipo":"general","pregunta":"Dos compañeros discuten. El que cae mejor a todo el mundo está defendiendo claramente una postura que el Perfeccionista considera injusta. ¿Qué tenderá a pesar más?","opciones":{"A":"Mantener la cohesión del grupo porque una discusión abierta puede empeorar el ambiente.","B":"Defender lo que considera correcto aunque eso implique ponerse contra la persona más popular.","C":"Esperar hasta conocer quién tiene más poder dentro de la empresa antes de posicionarse."},"correcta":"B","source_id":"AMPLIACION-20260815-014","modo":"personaje"},{"id":"AMP015","lote":5,"pagina":15,"eneatipo":1,"subtipo":"general","pregunta":"Al Perfeccionista le imponen un plazo imposible: o entrega algo mediocre el viernes o algo excelente fuera de fecha. ¿Dónde suele aparecer el verdadero conflicto?","opciones":{"A":"En decidir qué opción le hará quedar mejor ante sus superiores.","B":"En valorar qué opción comporta menos riesgo para su puesto.","C":"En aceptar conscientemente un resultado que considera insuficiente aunque racionalmente sepa que no puede hacerlo perfecto."},"correcta":"C","source_id":"AMPLIACION-20260815-015","modo":"personaje"},{"id":"AMP016","lote":5,"pagina":16,"eneatipo":1,"subtipo":"general","pregunta":"Un hotel ofrece al Perfeccionista una habitación de categoría superior, pero advierte que la han preparado a toda prisa y «quizá haya algún detalle sin revisar». Puede elegir también una habitación más sencilla impecablemente preparada. ¿Qué elección encaja mejor?","opciones":{"A":"Puede preferir la sencilla si siente que está correctamente hecha, aunque objetivamente tenga menos lujo.","B":"Elegirá la superior porque desaprovechar una mejora gratuita sería poco práctico.","C":"Elegirá la superior pero revisará antes todas las posibles consecuencias de aceptar el cambio."},"correcta":"A","source_id":"AMPLIACION-20260815-016","modo":"personaje"},{"id":"AMP017","lote":5,"pagina":17,"eneatipo":2,"subtipo":"general","pregunta":"La Encantadora ha estado muy pendiente de un amigo durante meses. Llega su cumpleaños y ese amigo se olvida por completo. ¿Qué puede dolerle especialmente?","opciones":{"A":"Que alguien haya incumplido una norma básica de educación.","B":"Descubrir que quizá no ocupa en la vida del otro el lugar especial que creía haber construido con todo lo que ha dado.","C":"Empezar a preguntarse si el olvido significa que esa persona ya no es fiable."},"correcta":"B","source_id":"AMPLIACION-20260815-017","modo":"personaje"},{"id":"AMP018","lote":5,"pagina":18,"eneatipo":2,"subtipo":"general","pregunta":"En una crisis familiar, la Encantadora organiza llamadas, lleva comida, encuentra soluciones y atiende a todo el mundo. Pasados unos días empieza a estar de muy mal humor. ¿Qué explicación encaja mejor?","opciones":{"A":"Le molesta que la familia no esté siguiendo correctamente sus instrucciones.","B":"Está saturado porque no ha tenido suficiente tiempo a solas para recuperar energía.","C":"Puede sentirse poco cuidado después de haber sido imprescindible para todos, aunque nunca haya pedido explícitamente que cuiden de él."},"correcta":"C","source_id":"AMPLIACION-20260815-018","modo":"personaje"},{"id":"AMP019","lote":5,"pagina":19,"eneatipo":2,"subtipo":"general","pregunta":"La pareja de la Encantadora le dice: «Necesito unos días para estar a mi aire». ¿Qué reacción automática podría aparecer aunque respete la petición?","opciones":{"A":"Buscar nuevas maneras de ser útil o atento para asegurarse de que el vínculo sigue vivo.","B":"Alejarse radicalmente para demostrar que nadie puede condicionarlo.","C":"Analizar todas las conversaciones anteriores intentando detectar en qué momento comenzó el problema."},"correcta":"A","source_id":"AMPLIACION-20260815-019","modo":"personaje"},{"id":"AMP020","lote":5,"pagina":20,"eneatipo":2,"subtipo":"general","pregunta":"Un equipo recibe un premio. La Encantadora no hizo la parte más visible, pero pasó semanas ayudando a cada compañero para que todo funcionara. Nadie menciona esa contribución. ¿Qué puede sentir?","opciones":{"A":"Que el premio carece de valor porque técnicamente el trabajo no era perfecto.","B":"Que una parte importante de lo que aportó ha quedado invisible y, por tanto, también él.","C":"Que debería haber calculado mejor quién iba a recibir finalmente el reconocimiento."},"correcta":"B","source_id":"AMPLIACION-20260815-020","modo":"personaje"},{"id":"AMP021","lote":5,"pagina":21,"eneatipo":2,"subtipo":"general","pregunta":"Un amigo rechaza varias veces la ayuda de la Encantadora diciendo: «De verdad, puedo hacerlo solo». Aunque la respuesta sea educada, ¿qué puede activar?","opciones":{"A":"La sensación de que el amigo es irresponsable por no aceptar una buena solución.","B":"El miedo de que el amigo esté tomando una decisión peligrosa.","C":"Una pequeña sensación de rechazo: si no necesita nada de él, puede preguntarse qué lugar ocupa entonces en el vínculo."},"correcta":"C","source_id":"AMPLIACION-20260815-021","modo":"personaje"},{"id":"AMP022","lote":5,"pagina":22,"eneatipo":2,"subtipo":"general","pregunta":"Una persona cercana consigue algo importante y la Encantadora dedica bastante tiempo a celebrarlo, organizarle una sorpresa y compartir orgullosamente su éxito. ¿Qué motivación encaja mejor con el patrón de la Encantadora?","opciones":{"A":"La alegría por participar de forma significativa en la vida del otro y reforzar mediante ello el vínculo especial que comparten.","B":"La necesidad de demostrar públicamente que pertenece al grupo de personas exitosas.","C":"El deseo de que la celebración se haga exactamente como corresponde."},"correcta":"A","source_id":"AMPLIACION-20260815-022","modo":"personaje"},{"id":"AMP023","lote":5,"pagina":23,"eneatipo":2,"subtipo":"general","pregunta":"La Encantadora presta una cantidad de dinero a un amigo. El amigo se la devuelve puntualmente, pero no dice gracias ni vuelve a mencionar el favor. ¿Qué puede molestarle más?","opciones":{"A":"Haber perdido durante unas semanas el control sobre ese dinero.","B":"Que el gesto haya sido tratado como una simple transacción cuando para él tenía también un significado relacional.","C":"Que el amigo no haya seguido un protocolo adecuado de agradecimiento."},"correcta":"B","source_id":"AMPLIACION-20260815-023","modo":"personaje"},{"id":"AMP024","lote":5,"pagina":24,"eneatipo":2,"subtipo":"general","pregunta":"En una fiesta, una persona que nadie conoce demasiado se queda sola porque acaba de recibir una mala noticia. ¿Qué reacción encaja mejor con la Encantadora?","opciones":{"A":"Esperar a que alguien con más confianza se acerque para no invadir.","B":"Observar desde lejos hasta comprender exactamente qué necesita esa persona.","C":"Acercarse, conectar rápidamente y empezar a ocuparse de ella casi como si llevaran años siendo amigos."},"correcta":"C","source_id":"AMPLIACION-20260815-024","modo":"personaje"},{"id":"AMP025","lote":5,"pagina":25,"eneatipo":2,"subtipo":"general","pregunta":"Un hermano le dice a la Encantadora: «A veces ayudas tanto que luego parece que te debemos algo». ¿Dónde puede estar el punto ciego?","opciones":{"A":"Puede vivir su ayuda como amor auténtico y no reconocer fácilmente las expectativas de reciprocidad que también se han creado.","B":"Puede estar usando la ayuda para demostrar que hace las cosas mejor que los demás.","C":"Puede estar utilizando los favores para evitar tomar decisiones importantes sobre su propia vida."},"correcta":"A","source_id":"AMPLIACION-20260815-025","modo":"personaje"},{"id":"AMP026","lote":5,"pagina":26,"eneatipo":2,"subtipo":"general","pregunta":"Llega un nuevo jefe que es correcto, eficiente y completamente distante: jamás pregunta nada personal ni parece necesitar ayuda. ¿Qué podría ocurrirle a la Encantadora?","opciones":{"A":"Sentirse muy cómodo porque por fin puede limitarse únicamente a sus tareas.","B":"Intentar descubrir de qué manera puede resultarle útil y construir algún tipo de conexión personal con él.","C":"Desconfiar automáticamente porque una autoridad que no explica sus emociones debe esconder algo."},"correcta":"B","source_id":"AMPLIACION-20260815-026","modo":"personaje"},{"id":"AMP027","lote":5,"pagina":27,"eneatipo":2,"subtipo":"general","pregunta":"Durante unas vacaciones cada miembro del grupo debe elegir una actividad. Cuando llega su turno, la Encantadora dice: «A mí me da igual, elegid vosotros». ¿Qué podría estar pasando realmente?","opciones":{"A":"No quiere elegir porque cualquier opción le parece una posible fuente de problemas.","B":"No tiene interés en ninguna actividad y prefiere conservar su energía.","C":"Puede renunciar genuinamente a su preferencia para agradar al grupo y esperar, quizá sin admitirlo, que ese gesto sea valorado."},"correcta":"C","source_id":"AMPLIACION-20260815-027","modo":"personaje"},{"id":"AMP028","lote":5,"pagina":28,"eneatipo":2,"subtipo":"general","pregunta":"La mejor amiga de la Encantadora consigue un trabajo increíble y, desde entonces, tiene muchísimo menos tiempo para él. ¿Qué conflicto es más probable?","opciones":{"A":"Puede alegrarse sinceramente por ella y al mismo tiempo notar que le inquieta dejar de ser tan necesario o central en su vida.","B":"Puede sentir que el trabajo de su amiga demuestra que su propia vida es menos especial.","C":"Puede pensar inmediatamente que la nueva empresa terminará aprovechándose de ella."},"correcta":"A","source_id":"AMPLIACION-20260815-028","modo":"personaje"},{"id":"AMP029","lote":5,"pagina":29,"eneatipo":2,"subtipo":"general","pregunta":"La Encantadora está agotado y había decidido pasar la tarde descansando. Su madre llama pidiéndole un favor que podría hacer perfectamente otra persona. ¿Qué reacción automática es probable?","opciones":{"A":"Negarse porque considera injusto que siempre recaiga en él.","B":"Decir que sí casi antes de comprobar si realmente quiere hacerlo y resentirse después por el esfuerzo.","C":"Pedir primero información detallada para calcular cuánto desgaste le supondrá."},"correcta":"B","source_id":"AMPLIACION-20260815-029","modo":"personaje"},{"id":"AMP030","lote":5,"pagina":30,"eneatipo":2,"subtipo":"general","pregunta":"Cuando la Encantadora atraviesa una mala época y necesita apoyo, ¿qué puede resultarle paradójicamente difícil?","opciones":{"A":"Confiar en que la otra persona sepa encontrar una solución práctica.","B":"Mostrar emociones porque teme perder autoridad.","C":"Pedir directamente lo que necesita, porque preferiría que alguien cercano se diera cuenta sin tener que reclamarlo."},"correcta":"C","source_id":"AMPLIACION-20260815-030","modo":"personaje"},{"id":"AMP031","lote":5,"pagina":31,"eneatipo":2,"subtipo":"general","pregunta":"Tras una ruptura, la expareja de la Encantadora le dice: «Has sido increíble conmigo; simplemente ya no quiero seguir». ¿Qué pensamiento puede aparecer?","opciones":{"A":"«Después de todo lo que he dado, ¿cómo puede no haber sido suficiente para que me quisiera?»","B":"«Si una relación termina, significa que alguno de los dos ha hecho algo moralmente incorrecto».","C":"«Debería haber detectado antes todas las señales de que esto podía pasar»."},"correcta":"A","source_id":"AMPLIACION-20260815-031","modo":"personaje"},{"id":"AMP032","lote":5,"pagina":32,"eneatipo":2,"subtipo":"general","pregunta":"Queda un único cruasán en una reunión. Un compañero le dice a la Encantadora: «Cógetelo tú». La Encantadora responde dos veces que no, que lo coja el otro. A la tercera, el compañero se lo come. ¿Qué reacción interna sería muy 2?","opciones":{"A":"Pensar únicamente que ha sido poco eficiente desperdiciar tanto tiempo decidiendo por un cruasán.","B":"Haberlo ofrecido sinceramente… y aun así sentir una diminuta indignación porque el otro finalmente aceptó.","C":"Alegrarse de que alguien haya tomado por fin una decisión y se haya acabado la tensión."},"correcta":"B","source_id":"AMPLIACION-20260815-032","modo":"personaje"},{"id":"AMP033","lote":5,"pagina":33,"eneatipo":3,"subtipo":"general","pregunta":"Una presentación del Triunfador sale mal delante de gente importante. ¿Qué reacción automática es más característica?","opciones":{"A":"Revisar durante horas cada error porque hacer un mal trabajo le resulta moralmente insoportable.","B":"Necesitar aislarse antes de decidir nada porque ha gastado demasiados recursos.","C":"Evaluar rápidamente cómo recuperar credibilidad y cuál debe ser el siguiente movimiento eficaz."},"correcta":"C","source_id":"AMPLIACION-20260815-033","modo":"personaje"},{"id":"AMP034","lote":5,"pagina":34,"eneatipo":3,"subtipo":"general","pregunta":"El hotel de unas vacaciones ha perdido la reserva del Triunfador y no quedan habitaciones. ¿Qué respuesta encaja mejor?","opciones":{"A":"Activarse para conseguir una alternativa, negociar una mejora y convertir el desastre en una solución presentable.","B":"Insistir principalmente en que el hotel reconozca que ha incumplido correctamente sus obligaciones.","C":"Empezar a imaginar otros fallos que podrían aparecer durante el viaje."},"correcta":"A","source_id":"AMPLIACION-20260815-034","modo":"personaje"},{"id":"AMP035","lote":5,"pagina":35,"eneatipo":3,"subtipo":"general","pregunta":"Un compañero consigue el ascenso que quería el Triunfador. ¿Qué reacción resulta especialmente coherente con su patrón?","opciones":{"A":"Pensar que el ascenso confirma que el compañero posee algo especial que a él siempre le faltará.","B":"Analizar qué resultados, habilidades o comportamientos están siendo premiados y adaptar su estrategia para la siguiente oportunidad.","C":"Confrontar al jefe directamente porque permitir que otro se coloque por encima resulta intolerable."},"correcta":"B","source_id":"AMPLIACION-20260815-035","modo":"personaje"},{"id":"AMP036","lote":5,"pagina":36,"eneatipo":3,"subtipo":"general","pregunta":"La pareja del Triunfador le pregunta: «¿Quién eres cuando no estás trabajando, consiguiendo cosas o cumpliendo algún objetivo?». ¿Por qué puede ser una pregunta incómoda?","opciones":{"A":"Porque considera una pérdida de tiempo hablar de identidad.","B":"Porque teme que cualquier respuesta pueda utilizarse contra él después.","C":"Porque puede haber desarrollado tan bien versiones eficaces de sí mismo que le cueste distinguirlas de lo que realmente quiere."},"correcta":"C","source_id":"AMPLIACION-20260815-036","modo":"personaje"},{"id":"AMP037","lote":5,"pagina":37,"eneatipo":3,"subtipo":"general","pregunta":"El Triunfador atraviesa un revés económico importante. ¿Qué impulso aparece con facilidad?","opciones":{"A":"Convertir rápidamente el problema en un plan: recortar lo inútil, generar nuevas vías de ingreso y recuperar sensación de eficacia.","B":"Reducir sus necesidades al mínimo para no depender jamás de nadie.","C":"Esperar antes de actuar hasta haber comprobado todos los escenarios en los que la situación podría empeorar."},"correcta":"A","source_id":"AMPLIACION-20260815-037","modo":"personaje"},{"id":"AMP038","lote":5,"pagina":38,"eneatipo":3,"subtipo":"general","pregunta":"Una publicación en redes sociales en la que el Triunfador había puesto bastante esfuerzo tiene poquísima repercusión. ¿Qué es probable que haga?","opciones":{"A":"Mantener exactamente el mismo estilo porque cambiarlo sería traicionar quién es.","B":"Estudiar qué ha fallado, qué funciona mejor con ese público y ajustar la siguiente publicación.","C":"Desaparecer un tiempo porque la exposición social consume demasiada energía."},"correcta":"B","source_id":"AMPLIACION-20260815-038","modo":"personaje"},{"id":"AMP039","lote":5,"pagina":39,"eneatipo":3,"subtipo":"general","pregunta":"El Triunfador tiene un jefe bastante mediocre que, sin embargo, controla promociones y proyectos visibles. ¿Qué estrategia puede aparecer?","opciones":{"A":"Corregirlo abiertamente cada vez que incumpla un criterio profesional.","B":"Desafiarlo frontalmente para dejar claro quién es realmente más fuerte.","C":"Aprender a gestionar la relación con él mientras toma discretamente las riendas de aquello que necesita salir bien."},"correcta":"C","source_id":"AMPLIACION-20260815-039","modo":"personaje"},{"id":"AMP040","lote":5,"pagina":40,"eneatipo":3,"subtipo":"general","pregunta":"Un amigo le dice al Triunfador: «Cuando nos vemos solo me cuentas lo bien que te va. No sé cómo estás de verdad». ¿Qué puede haber detrás de esa conducta?","opciones":{"A":"Puede mostrar espontáneamente su versión más valiosa y competente, hasta el punto de ocultar también ante sí mismo lo que no encaja en ella.","B":"Puede pensar que hablar de problemas supone cargar injustamente a los demás.","C":"Puede necesitar analizar sus emociones a solas antes de poder compartirlas."},"correcta":"A","source_id":"AMPLIACION-20260815-040","modo":"personaje"},{"id":"AMP041","lote":5,"pagina":41,"eneatipo":3,"subtipo":"general","pregunta":"El Triunfador suspende una prueba importante. Después del golpe inicial, ¿qué reacción es más típica?","opciones":{"A":"Quedarse enganchado a la sensación de que el resultado demuestra que nunca fue suficientemente especial.","B":"Averiguar qué puntuación necesita, detectar qué no funcionó y modificar el método para volver a intentarlo.","C":"Preguntar a varias personas si creen que el examen estaba realmente bien diseñado."},"correcta":"B","source_id":"AMPLIACION-20260815-041","modo":"personaje"},{"id":"AMP042","lote":5,"pagina":42,"eneatipo":3,"subtipo":"general","pregunta":"El Triunfador tiene por fin un fin de semana sin trabajo, compromisos ni objetivos. ¿Qué podría ocurrir?","opciones":{"A":"Disfrutar especialmente de no tener absolutamente nada que optimizar.","B":"Aprovecharlo para retirarse del contacto y no gastar energía social.","C":"Convertir incluso el ocio en algo con cierta meta: hacer «la mejor ruta», terminar un reto o aprovechar el día al máximo."},"correcta":"C","source_id":"AMPLIACION-20260815-042","modo":"personaje"},{"id":"AMP043","lote":5,"pagina":43,"eneatipo":3,"subtipo":"general","pregunta":"Un proyecto de equipo sale magníficamente y todo el mundo felicita públicamente al Triunfador por su papel. ¿Por qué ese reconocimiento puede tener tanto peso?","opciones":{"A":"Porque confirma externamente la imagen de persona competente y valiosa que intenta sostener con sus resultados.","B":"Porque demuestra que el grupo depende afectivamente de él.","C":"Porque significa que ha actuado exactamente según sus principios internos."},"correcta":"A","source_id":"AMPLIACION-20260815-043","modo":"personaje"},{"id":"AMP044","lote":5,"pagina":44,"eneatipo":3,"subtipo":"general","pregunta":"Al Triunfador le ofrecen dos proyectos: uno es muy estimulante pero irrelevante para su carrera; el otro, bastante aburrido pero con enorme visibilidad y posibilidades de promoción. ¿Qué elección podría diferenciarlo de la Ilusionista?","opciones":{"A":"Escoger el estimulante porque la energía del momento siempre pesa más que el resultado futuro.","B":"Elegir el proyecto aburrido si entiende que es la vía más eficaz hacia el objetivo que se ha marcado.","C":"Rechazar ambos hasta saber cuál comporta menos incertidumbre."},"correcta":"B","source_id":"AMPLIACION-20260815-044","modo":"personaje"},{"id":"AMP045","lote":5,"pagina":45,"eneatipo":3,"subtipo":"general","pregunta":"La pareja del Triunfador le acusa de ser una persona distinta con sus amigos, con su familia y en el trabajo. ¿Cómo puede vivirlo él?","opciones":{"A":"Como prueba de que esas personas intentan limitar su libertad.","B":"Como una muestra de que todavía no conoce suficientemente bien cada ambiente.","C":"Puede no verlo como falsedad, sino como una capacidad natural para convertirse en la versión que mejor funciona en cada contexto."},"correcta":"C","source_id":"AMPLIACION-20260815-045","modo":"personaje"},{"id":"AMP046","lote":5,"pagina":46,"eneatipo":3,"subtipo":"general","pregunta":"El Triunfador pierde inesperadamente un trabajo prestigioso. ¿Qué parte del golpe puede ser especialmente fuerte?","opciones":{"A":"No solo perder el empleo, sino perder de repente una identidad que demostraba quién era y cuánto valía.","B":"Que la empresa haya incumplido el modo correcto de tratar a un empleado.","C":"Que ahora deba depender temporalmente de recursos externos."},"correcta":"A","source_id":"AMPLIACION-20260815-046","modo":"personaje"},{"id":"AMP047","lote":5,"pagina":47,"eneatipo":3,"subtipo":"general","pregunta":"Le encargan al Triunfador una tarea creativa sin criterios, métricas ni una definición clara de qué significa «hacerlo bien». ¿Qué puede incomodarle?","opciones":{"A":"No tener suficiente privacidad para desarrollar sus ideas.","B":"No disponer de una referencia clara que le permita saber si está teniendo éxito.","C":"Que la tarea no tenga suficiente significado emocional y personal."},"correcta":"B","source_id":"AMPLIACION-20260815-047","modo":"personaje"},{"id":"AMP048","lote":5,"pagina":48,"eneatipo":3,"subtipo":"general","pregunta":"En una cena de empresa montan un karaoke delante de clientes y directivos. ¿Qué elección sería muy 3?","opciones":{"A":"Cantar su canción favorita aunque sepa que se le da fatal, porque es la que más representa quién es.","B":"Negarse hasta conocer exactamente qué riesgos sociales tendría participar.","C":"Elegir una canción que sabe que puede defender bien y leer la sala para que la actuación funcione."},"correcta":"C","source_id":"AMPLIACION-20260815-048","modo":"personaje"},{"id":"AMP049","lote":5,"pagina":49,"eneatipo":4,"subtipo":"general","pregunta":"Una amiga enseña orgullosa a la Artista su nueva casa, decorada exactamente igual que decenas de fotos de moda que circulan por internet. ¿Qué puede chirriarle?","opciones":{"A":"La sensación de que todo es correcto pero no cuenta nada particular sobre quien vive allí.","B":"Que algunos muebles no estén perfectamente alineados.","C":"Que esa decoración no proyecte suficiente éxito social."},"correcta":"A","source_id":"AMPLIACION-20260815-049","modo":"personaje"},{"id":"AMP050","lote":5,"pagina":50,"eneatipo":4,"subtipo":"general","pregunta":"La pareja de la Artista puede regalarle un reloj muy caro y bastante impersonal o un objeto barato hecho especialmente para él con una historia detrás. ¿Cuál suele tener más posibilidades de impactarle?","opciones":{"A":"El reloj, porque demuestra objetivamente cuánto se ha invertido en la relación.","B":"El objeto personal, si siente que contiene algo que solo podría tener sentido entre ellos dos.","C":"Cualquiera de los dos, siempre que haya sido elegido siguiendo lo que se esperaba socialmente."},"correcta":"B","source_id":"AMPLIACION-20260815-050","modo":"personaje"},{"id":"AMP051","lote":5,"pagina":51,"eneatipo":4,"subtipo":"general","pregunta":"La Artista consigue por fin algo que llevaba años idealizando. Poco después empieza a sentir una extraña insatisfacción. ¿Qué dinámica encaja mejor?","opciones":{"A":"El miedo a no poder conservar lo conseguido y perder la seguridad alcanzada.","B":"La necesidad inmediata de fijarse una meta más rentable o prestigiosa.","C":"La tendencia a desplazar la atención hacia aquello que todavía falta, incluso después de alcanzar lo deseado."},"correcta":"C","source_id":"AMPLIACION-20260815-051","modo":"personaje"},{"id":"AMP052","lote":5,"pagina":52,"eneatipo":4,"subtipo":"general","pregunta":"En una reunión familiar comparan favorablemente a la Artista con su hermano: «Sois igualitos, los dos tenéis muchísimo talento». Sorprendentemente, el comentario le molesta. ¿Por qué?","opciones":{"A":"Porque incluso una comparación positiva puede hacerle sentir que están borrando aquello que lo hace singular.","B":"Porque cree que el mérito debería atribuirse con criterios más objetivos.","C":"Porque empieza a preguntarse cuál de los dos tiene realmente más éxito."},"correcta":"A","source_id":"AMPLIACION-20260815-052","modo":"personaje"},{"id":"AMP053","lote":5,"pagina":53,"eneatipo":4,"subtipo":"general","pregunta":"La Artista descubre en redes a alguien que vive exactamente el tipo de vida que él había imaginado para sí. ¿Qué reacción es especialmente probable?","opciones":{"A":"Desinterés, porque cuando algo ya existe deja de tener ningún atractivo.","B":"Una mezcla incómoda de fascinación y dolor: «eso se parece demasiado a algo que siento que debería haber sido mío».","C":"Preocupación por si esa persona está asumiendo demasiados riesgos para sostener esa vida."},"correcta":"B","source_id":"AMPLIACION-20260815-053","modo":"personaje"},{"id":"AMP054","lote":5,"pagina":54,"eneatipo":4,"subtipo":"general","pregunta":"En plena discusión alguien le dice a la Artista: «No hagas un drama, esto le pasa a todo el mundo». ¿Qué puede resultar especialmente irritante?","opciones":{"A":"Que la otra persona esté incumpliendo las reglas básicas de una discusión justa.","B":"Que intente ganar la conversación mostrando más autoridad.","C":"Que reduzca una experiencia que él vive con significado propio a algo genérico e intercambiable."},"correcta":"C","source_id":"AMPLIACION-20260815-054","modo":"personaje"},{"id":"AMP055","lote":5,"pagina":55,"eneatipo":4,"subtipo":"general","pregunta":"En el trabajo piden a la Artista que convierta una idea personal en algo «mucho más genérico, que guste a todo el mundo». ¿Dónde puede aparecer resistencia?","opciones":{"A":"En sentir que, para funcionar comercialmente, está vaciando la propuesta de aquello que la hacía realmente suya.","B":"En que la petición no haya seguido correctamente el procedimiento de aprobación.","C":"En sospechar que la dirección no conoce todos los riesgos del cambio."},"correcta":"A","source_id":"AMPLIACION-20260815-055","modo":"personaje"},{"id":"AMP056","lote":5,"pagina":56,"eneatipo":4,"subtipo":"general","pregunta":"Durante un viaje, la Artista puede elegir entre una atracción turística impecable y muy popular o un pueblo medio abandonado con una historia rarísima detrás. ¿Qué podría atraerle del segundo?","opciones":{"A":"Que haya menos gente y así pueda conservar su energía.","B":"La sensación de atmósfera, historia y singularidad, aunque objetivamente sea menos cómodo.","C":"Que visitar un sitio poco conocido le permita demostrar que sabe viajar mejor que los demás."},"correcta":"B","source_id":"AMPLIACION-20260815-056","modo":"personaje"},{"id":"AMP057","lote":5,"pagina":57,"eneatipo":4,"subtipo":"general","pregunta":"La Artista cuenta algo que le ha dolido y recibe como respuesta: «No te preocupes, eso nos pasa a todos». ¿Por qué la frase puede no consolarle?","opciones":{"A":"Porque preferiría que la otra persona le ofreciese inmediatamente una solución.","B":"Porque necesita comprobar primero que quien le escucha es totalmente fiable.","C":"Porque universalizar lo que siente puede hacerle experimentar que se está perdiendo el matiz particular de su vivencia."},"correcta":"C","source_id":"AMPLIACION-20260815-057","modo":"personaje"},{"id":"AMP058","lote":5,"pagina":58,"eneatipo":4,"subtipo":"general","pregunta":"La vida de la Artista lleva meses funcionando sorprendentemente bien: estabilidad, buenas relaciones y pocos problemas. Aun así empieza a sentir cierta inquietud. ¿Qué podría estar ocurriendo?","opciones":{"A":"La ausencia de intensidad puede hacerle buscar qué falta o preguntarse si una vida tan plana refleja realmente quién es.","B":"Necesita generar nuevos objetivos porque no soporta no estar avanzando profesionalmente.","C":"Empieza a prepararse para la desgracia porque tanta tranquilidad le parece sospechosa."},"correcta":"A","source_id":"AMPLIACION-20260815-058","modo":"personaje"},{"id":"AMP059","lote":5,"pagina":59,"eneatipo":4,"subtipo":"general","pregunta":"La Artista pierde un concurso frente a una propuesta técnicamente impecable que le parece completamente convencional. ¿Qué puede escocerle especialmente?","opciones":{"A":"Haber cometido errores que un profesional competente no debería cometer.","B":"Que aquello que considera más original o significativo no haya sido reconocido por los criterios dominantes.","C":"No haber estudiado suficientemente bien las probabilidades antes de presentarse."},"correcta":"B","source_id":"AMPLIACION-20260815-059","modo":"personaje"},{"id":"AMP060","lote":5,"pagina":60,"eneatipo":4,"subtipo":"general","pregunta":"Una empresa impone un uniforme muy rígido en un puesto donde antes cada uno podía vestir como quisiera. ¿Qué puede molestar a la Artista más allá de la ropa?","opciones":{"A":"Que la empresa esté malgastando dinero en prendas innecesarias.","B":"Que nadie haya consultado si el uniforme resulta eficiente para trabajar.","C":"La sensación de ser convertido visualmente en una pieza intercambiable con el resto."},"correcta":"C","source_id":"AMPLIACION-20260815-060","modo":"personaje"},{"id":"AMP061","lote":5,"pagina":61,"eneatipo":4,"subtipo":"general","pregunta":"Después de perder a alguien importante, la Artista conserva durante años un objeto aparentemente inútil relacionado con esa persona. ¿Qué explicación encaja mejor?","opciones":{"A":"El objeto mantiene vivo un significado y una continuidad emocional que no depende de su utilidad práctica.","B":"Tirarlo le preocupa porque quizá algún día pueda necesitarlo.","C":"Cree que deshacerse de él sería objetivamente incorrecto y una falta de disciplina."},"correcta":"A","source_id":"AMPLIACION-20260815-061","modo":"personaje"},{"id":"AMP062","lote":5,"pagina":62,"eneatipo":4,"subtipo":"general","pregunta":"Después de una discusión importante, la pareja de la Artista pregunta con toda naturalidad: «Bueno, ¿qué cenamos?». ¿Qué reacción puede aparecer?","opciones":{"A":"Alivio porque cambiar de tema evita prolongar un conflicto desagradable.","B":"Resistencia a volver a la normalidad mientras siente que algo emocionalmente significativo sigue sin resolverse.","C":"Aprovechar para proponer un plan distinto y cambiar rápidamente de ambiente."},"correcta":"B","source_id":"AMPLIACION-20260815-062","modo":"personaje"},{"id":"AMP063","lote":5,"pagina":63,"eneatipo":4,"subtipo":"general","pregunta":"La Artista puede permitirse una única compra: un electrodoméstico que le resolvería bastantes problemas prácticos o una obra que le provoca algo especial cada vez que la mira. ¿Qué elección no sería extraña?","opciones":{"A":"El electrodoméstico, porque lo importante es conservar recursos y autonomía.","B":"El electrodoméstico, porque una compra debe justificarse siempre por su eficiencia.","C":"La obra, si siente que tiene un significado personal que compensa su escasa utilidad."},"correcta":"C","source_id":"AMPLIACION-20260815-063","modo":"personaje"},{"id":"AMP064","lote":5,"pagina":64,"eneatipo":4,"subtipo":"general","pregunta":"Invitan a la Artista a una fiesta de disfraces cuyo tema es: «Ven vestido de ti mismo». ¿Qué podría ocurrir?","opciones":{"A":"Que convierta una consigna aparentemente facilísima en un pequeño problema existencial sobre qué versión de sí mismo es realmente la auténtica.","B":"Que elija rápidamente el atuendo que mejor impresión provoque al grupo.","C":"Que no vaya hasta saber exactamente cómo irá vestida la mayoría."},"correcta":"A","source_id":"AMPLIACION-20260815-064","modo":"personaje"},{"id":"AMP065","lote":5,"pagina":65,"eneatipo":5,"subtipo":"general","pregunta":"En una reunión preguntan de improviso al Investigador su opinión sobre un tema que apenas conoce. ¿Qué reacción encaja mejor?","opciones":{"A":"Dar una respuesta convincente para no parecer poco competente.","B":"Preferir admitir que necesita más información antes de posicionarse con seguridad.","C":"Preguntar qué piensa la mayoría antes de comprometerse."},"correcta":"B","source_id":"AMPLIACION-20260815-065","modo":"personaje"},{"id":"AMP066","lote":5,"pagina":66,"eneatipo":5,"subtipo":"general","pregunta":"La pareja del Investigador escribe a mediodía: «Esta noche vienen seis amigos a cenar a casa». Él aprecia a esas personas. Aun así, ¿qué puede molestarle?","opciones":{"A":"Que la cena no esté organizada con suficiente precisión.","B":"Que ninguno de esos amigos haya preguntado antes si el plan era adecuado.","C":"Que de repente se haya comprometido su espacio, su tiempo y su energía sin margen para prepararse."},"correcta":"C","source_id":"AMPLIACION-20260815-066","modo":"personaje"},{"id":"AMP067","lote":5,"pagina":67,"eneatipo":5,"subtipo":"general","pregunta":"El Investigador descubre que lleva meses pagando una suscripción barata que apenas utiliza. ¿Por qué puede cancelarla inmediatamente aunque el importe sea ridículo?","opciones":{"A":"Porque le incomodan los pequeños drenajes continuos de recursos que no le aportan nada a cambio.","B":"Porque considera inmoral pagar por algo que no aprovecha completamente.","C":"Porque teme que la empresa suba el precio inesperadamente en el futuro."},"correcta":"A","source_id":"AMPLIACION-20260815-067","modo":"personaje"},{"id":"AMP068","lote":5,"pagina":68,"eneatipo":5,"subtipo":"general","pregunta":"Un grupo de WhatsApp acumula 200 mensajes en una mañana. ¿Qué conducta encaja mejor con el Investigador?","opciones":{"A":"Responder a todos para demostrar que sigue formando parte activa del grupo.","B":"Silenciarlo, revisarlo cuando él decida y contestar solo a aquello que considera relevante.","C":"Leerlo constantemente para comprobar si aparece alguna información que pueda afectarle."},"correcta":"B","source_id":"AMPLIACION-20260815-068","modo":"personaje"},{"id":"AMP069","lote":5,"pagina":69,"eneatipo":5,"subtipo":"general","pregunta":"La pareja del Investigador está llorando y le dice: «No quiero soluciones, solo dime algo». ¿Qué dificultad puede aparecer?","opciones":{"A":"Puede enfadarse porque considera que llorar no resuelve nada.","B":"Puede cambiar de tema para que el ambiente recupere rápidamente la normalidad.","C":"Puede necesitar retirarse mentalmente para procesar lo que ocurre y parecer frío justo cuando se le exige una respuesta emocional inmediata."},"correcta":"C","source_id":"AMPLIACION-20260815-069","modo":"personaje"},{"id":"AMP070","lote":5,"pagina":70,"eneatipo":5,"subtipo":"general","pregunta":"Un jefe encarga una tarea completamente nueva al Investigador y le dice: «No investigues tanto, lánzate y ya irás viendo». ¿Qué puede incomodarle?","opciones":{"A":"Empezar a actuar antes de comprender mínimamente el sistema en el que se está metiendo.","B":"No saber si el trabajo tendrá suficiente reconocimiento externo.","C":"Que improvisar pueda romper alguna regla profesional importante."},"correcta":"A","source_id":"AMPLIACION-20260815-070","modo":"personaje"},{"id":"AMP071","lote":5,"pagina":71,"eneatipo":5,"subtipo":"general","pregunta":"En unas vacaciones, el resto del grupo propone actividades desde las ocho de la mañana hasta medianoche todos los días. ¿Qué es probable que eche de menos el Investigador?","opciones":{"A":"Una actividad más intensa que haga que el viaje merezca realmente la pena.","B":"Espacios vacíos en los que no tenga que relacionarse, responder ni estar disponible para nadie.","C":"Un plan mejor estructurado para que nadie desperdicie tiempo."},"correcta":"B","source_id":"AMPLIACION-20260815-071","modo":"personaje"},{"id":"AMP072","lote":5,"pagina":72,"eneatipo":5,"subtipo":"general","pregunta":"Un amigo devuelve siempre tarde los libros y herramientas que pide prestados al Investigador. ¿Qué puede explicar que esto le irrite más de lo esperado?","opciones":{"A":"Considera objetivamente incorrecto no devolver algo en el plazo acordado.","B":"Empieza a sospechar que el amigo no es una persona fiable en general.","C":"Sus objetos y recursos forman parte de un territorio controlado, y prestarlos ya supone abrir temporalmente ese territorio."},"correcta":"C","source_id":"AMPLIACION-20260815-072","modo":"personaje"},{"id":"AMP073","lote":5,"pagina":73,"eneatipo":5,"subtipo":"general","pregunta":"El Investigador se convierte inesperadamente en un referente dentro de su profesión y comienzan a invitarlo a conferencias. ¿Qué contradicción puede aparecer?","opciones":{"A":"Le gusta que se valore su conocimiento, pero puede incomodarle el nivel de exposición y disponibilidad que viene asociado al reconocimiento.","B":"Le preocupa no poder convertir esa fama rápidamente en mejores resultados económicos.","C":"Se siente culpable porque destacar por encima de sus compañeros le parece injusto."},"correcta":"A","source_id":"AMPLIACION-20260815-073","modo":"personaje"},{"id":"AMP074","lote":5,"pagina":74,"eneatipo":5,"subtipo":"general","pregunta":"La familia reprocha al Investigador: «Si nos quisieras más, llamarías más». ¿Qué podría estar ocurriendo realmente?","opciones":{"A":"Está castigándolos silenciosamente para evitar tener una discusión directa.","B":"Puede sentir el vínculo sin necesitar una frecuencia de contacto que los demás interpretan como prueba de cariño.","C":"Está esperando a que sean ellos quienes demuestren primero que realmente lo necesitan."},"correcta":"B","source_id":"AMPLIACION-20260815-074","modo":"personaje"},{"id":"AMP075","lote":5,"pagina":75,"eneatipo":5,"subtipo":"general","pregunta":"Cinco personas están encerradas en una escape room y empiezan a hablar todas a la vez porque quedan diez minutos. ¿Qué reacción sería bastante 5?","opciones":{"A":"Tomar el mando inmediatamente y asignar funciones a gritos.","B":"Intentar rebajar el conflicto para que todo el mundo vuelva a estar tranquilo.","C":"Apartarse un momento del ruido, observar el conjunto y ordenar mentalmente las pistas antes de intervenir."},"correcta":"C","source_id":"AMPLIACION-20260815-075","modo":"personaje"},{"id":"AMP076","lote":5,"pagina":76,"eneatipo":5,"subtipo":"general","pregunta":"El Investigador atraviesa un problema para el que necesitaría pedir dinero o ayuda material a alguien cercano. ¿Qué puede hacer que retrase la petición?","opciones":{"A":"Pedir ayuda puede introducir dependencia, deuda y nuevas demandas en una vida que intenta mantener bajo su propio control.","B":"Teme principalmente que la otra persona deje de admirarlo.","C":"Cree que aceptar ayuda sería moralmente incorrecto si existe cualquier posibilidad de arreglarlo solo."},"correcta":"A","source_id":"AMPLIACION-20260815-076","modo":"personaje"},{"id":"AMP077","lote":5,"pagina":77,"eneatipo":5,"subtipo":"general","pregunta":"En una reunión de trabajo, varias personas hablan durante veinte minutos para repetir prácticamente la misma idea. El Investigador apenas interviene. ¿Qué explicación encaja mejor?","opciones":{"A":"Tiene miedo de equivocarse delante del grupo.","B":"No siente necesidad de gastar palabras si considera que no tiene información nueva que añadir.","C":"Está molesto porque los demás están recibiendo más atención que él."},"correcta":"B","source_id":"AMPLIACION-20260815-077","modo":"personaje"},{"id":"AMP078","lote":5,"pagina":78,"eneatipo":5,"subtipo":"general","pregunta":"El Investigador debe firmar un contrato complejo con una empresa aparentemente fiable. ¿Qué conducta es más probable?","opciones":{"A":"Firmarlo si la persona que se lo recomienda tiene suficiente autoridad.","B":"Rechazarlo si cualquier cláusula le parece moralmente discutible, aunque no le afecte.","C":"Investigar por su cuenta las condiciones hasta sentir que entiende bien qué compromisos está adquiriendo."},"correcta":"C","source_id":"AMPLIACION-20260815-078","modo":"personaje"},{"id":"AMP079","lote":5,"pagina":79,"eneatipo":5,"subtipo":"general","pregunta":"Un viernes la pareja del Investigador propone: «Mañana nos vamos a otro país. He visto vuelos baratos». ¿Qué podría hacer que su primera reacción sea negativa?","opciones":{"A":"La cantidad repentina de logística, exposición y recursos que debe movilizar sin tiempo para prepararse.","B":"El miedo a que el destino resulte decepcionante y desperdiciar una oportunidad mejor.","C":"La posibilidad de que el viaje no esté suficientemente bien organizado."},"correcta":"A","source_id":"AMPLIACION-20260815-079","modo":"personaje"},{"id":"AMP080","lote":5,"pagina":80,"eneatipo":5,"subtipo":"general","pregunta":"Durante una fiesta en casa del Investigador, un invitado abre sin preguntar un cajón de su escritorio buscando un cargador. ¿Qué puede hacer que el gesto le siente especialmente mal?","opciones":{"A":"Que el invitado haya dejado el cajón desordenado.","B":"Que alguien haya cruzado sin permiso una frontera entre lo compartido y aquello que él considera privado.","C":"Que esa persona quizá encuentre algo con lo que pueda juzgarlo."},"correcta":"B","source_id":"AMPLIACION-20260815-080","modo":"personaje"},{"id":"AMP081","lote":5,"pagina":81,"eneatipo":6,"subtipo":"general","pregunta":"La Prevencionista recibe un mensaje de su pareja que solo dice: «Luego tenemos que hablar». Faltan cuatro horas para verla. ¿Qué es probable que haga su cabeza?","opciones":{"A":"Pensar que cualquier problema podrá resolverse cuando llegue el momento y olvidarse del asunto.","B":"Decidir cuál sería la respuesta más correcta antes de conocer siquiera el tema.","C":"Generar varias hipótesis, revisar conversaciones anteriores y buscar pistas sobre qué puede estar pasando."},"correcta":"C","source_id":"AMPLIACION-20260815-081","modo":"personaje"},{"id":"AMP082","lote":5,"pagina":82,"eneatipo":6,"subtipo":"general","pregunta":"Un nuevo jefe dice al equipo: «Confiad en mí. No hace falta que os explique todavía el plan». ¿Cómo puede reaccionar la Prevencionista?","opciones":{"A":"La petición de confianza sin información puede aumentar su desconfianza en lugar de tranquilizarlo.","B":"Le irritará principalmente que el jefe esté intentando imponer su poder sobre él.","C":"Le parecerá perfecto siempre que el jefe proyecte una imagen suficientemente competente."},"correcta":"A","source_id":"AMPLIACION-20260815-082","modo":"personaje"},{"id":"AMP083","lote":5,"pagina":83,"eneatipo":6,"subtipo":"general","pregunta":"Un vuelo muy barato tiene una escala de solo 45 minutos. ¿Qué comportamiento encaja mejor con la Prevencionista?","opciones":{"A":"Rechazar automáticamente cualquier opción que tenga un mínimo de riesgo.","B":"Comprobar terminales, estadísticas de puntualidad y alternativas en caso de perder la conexión antes de decidir.","C":"Reservarlo inmediatamente porque siempre puede improvisar si algo sale mal."},"correcta":"B","source_id":"AMPLIACION-20260815-083","modo":"personaje"},{"id":"AMP084","lote":5,"pagina":84,"eneatipo":6,"subtipo":"general","pregunta":"La pareja de la Prevencionista llega a casa mucho más alegre de lo habitual y no explica por qué. ¿Qué podría activar su atención?","opciones":{"A":"La sensación de que la pareja está intentando destacar demasiado.","B":"El enfado porque los cambios de humor deberían controlarse mejor.","C":"La discrepancia: «¿Qué ha pasado para que hoy esté así?» y la necesidad de comprobar si existe información que desconoce."},"correcta":"C","source_id":"AMPLIACION-20260815-084","modo":"personaje"},{"id":"AMP085","lote":5,"pagina":85,"eneatipo":6,"subtipo":"general","pregunta":"Un superior da hoy unas instrucciones que contradicen lo que ordenó ayer. ¿Qué es muy probable que haga la Prevencionista?","opciones":{"A":"Pedir aclaraciones y, si el asunto es importante, intentar dejar claro cuál es finalmente el criterio que debe seguirse.","B":"Elegir directamente la versión que considera moralmente correcta.","C":"Seguir la nueva orden y concentrarse en que el resultado final quede bien ante la dirección."},"correcta":"A","source_id":"AMPLIACION-20260815-085","modo":"personaje"},{"id":"AMP086","lote":5,"pagina":86,"eneatipo":6,"subtipo":"general","pregunta":"Un grupo de amigos quiere invertir conjuntamente en una idea que parece prometedora. Todos están emocionados salvo la Prevencionista, que empieza a plantear preguntas incómodas. ¿Qué está haciendo?","opciones":{"A":"Intentando demostrar que entiende mejor el negocio que los demás.","B":"Localizando dónde podría romperse el plan y qué ocurriría con cada persona si eso sucede.","C":"Evitando comprometer recursos porque compartirlos le hace sentir invadido."},"correcta":"B","source_id":"AMPLIACION-20260815-086","modo":"personaje"},{"id":"AMP087","lote":5,"pagina":87,"eneatipo":6,"subtipo":"general","pregunta":"Un amigo cancela dos veces planes con la Prevencionista utilizando excusas bastante vagas. ¿Qué puede molestarle más?","opciones":{"A":"Que el amigo no respete correctamente un compromiso.","B":"Que quizá prefiera pasar el tiempo con otras personas más interesantes.","C":"No saber si las excusas son ciertas ni hasta qué punto puede contar realmente con esa persona."},"correcta":"C","source_id":"AMPLIACION-20260815-087","modo":"personaje"},{"id":"AMP088","lote":5,"pagina":88,"eneatipo":6,"subtipo":"general","pregunta":"Ante una persona muy segura de sí misma, la Prevencionista puede parecer a veces obediente y otras sorprendentemente desafiante. ¿Qué une ambas respuestas?","opciones":{"A":"Está intentando averiguar si esa autoridad merece realmente confianza o necesita ser puesta a prueba.","B":"Cambia de comportamiento para proyectar la imagen que mejor le conviene.","C":"Reacciona según la cantidad de libertad personal que esa persona le permita."},"correcta":"A","source_id":"AMPLIACION-20260815-088","modo":"personaje"},{"id":"AMP089","lote":5,"pagina":89,"eneatipo":6,"subtipo":"general","pregunta":"Después de años con contratos temporales, la Prevencionista consigue por fin un puesto fijo. ¿Qué puede ocurrir poco después del alivio inicial?","opciones":{"A":"Sentir que tener estabilidad le impide descubrir nuevas posibilidades.","B":"Que su mente encuentre la siguiente posible amenaza: una reestructuración, un cambio de jefe o cualquier escenario que vuelva a poner la seguridad en cuestión.","C":"Empezar a buscar un puesto más prestigioso porque la meta conseguida ya no demuestra suficiente valor."},"correcta":"B","source_id":"AMPLIACION-20260815-089","modo":"personaje"},{"id":"AMP090","lote":5,"pagina":90,"eneatipo":6,"subtipo":"general","pregunta":"Circulan tres versiones contradictorias sobre un problema que afecta al trabajo de la Prevencionista. ¿Qué reacción es probable?","opciones":{"A":"Elegir la explicación que le permita actuar más rápido.","B":"Confiar en la versión de la persona con mayor rango.","C":"Comparar fuentes, preguntar a personas fiables e intentar construir una explicación suficientemente consistente antes de relajarse."},"correcta":"C","source_id":"AMPLIACION-20260815-090","modo":"personaje"},{"id":"AMP091","lote":5,"pagina":91,"eneatipo":6,"subtipo":"general","pregunta":"Durante una emergencia real, la Prevencionista que normalmente parece preocupado sorprende a todo el mundo reaccionando con gran eficacia. ¿Por qué no es contradictorio?","opciones":{"A":"Cuando el peligro deja de ser hipotético y se vuelve concreto, toda su preparación puede transformarse rápidamente en acción.","B":"Las emergencias le permiten demostrar públicamente cuánto vale.","C":"En una crisis ya no tiene que preocuparse de hacer las cosas correctamente."},"correcta":"A","source_id":"AMPLIACION-20260815-091","modo":"personaje"},{"id":"AMP092","lote":5,"pagina":92,"eneatipo":6,"subtipo":"general","pregunta":"Un amigo le dice a la Prevencionista: «Siempre estás pensando en lo que puede salir mal». ¿Cómo puede entender él esa conducta?","opciones":{"A":"Como una forma inevitable de demostrar cariño a los demás.","B":"Como una responsabilidad: alguien tiene que detectar los agujeros antes de que todo el mundo caiga por ellos.","C":"Como una manera de conservar suficiente distancia respecto a cualquier compromiso."},"correcta":"B","source_id":"AMPLIACION-20260815-092","modo":"personaje"},{"id":"AMP093","lote":5,"pagina":93,"eneatipo":6,"subtipo":"general","pregunta":"Un protocolo oficial ordena hacer algo que, según la información disponible, parece claramente inseguro. ¿Qué demuestra mejor la complejidad de la Prevencionista?","opciones":{"A":"Lo seguirá siempre porque la Prevencionista obedece a cualquier autoridad.","B":"Lo romperá solo para demostrar que nadie puede controlarlo.","C":"Puede desafiarlo si concluye que la autoridad o el sistema encargado de protegerlo ya no es fiable."},"correcta":"C","source_id":"AMPLIACION-20260815-093","modo":"personaje"},{"id":"AMP094","lote":5,"pagina":94,"eneatipo":6,"subtipo":"general","pregunta":"Un buen amigo pide a la Prevencionista que avale personalmente un préstamo y le dice: «No te preocupes, jamás tendrás que pagar nada». ¿Qué es probable?","opciones":{"A":"Preguntar exactamente qué obligaciones asumiría y qué ocurriría en los escenarios en los que su amigo no pudiera pagar.","B":"Aceptar porque la lealtad hacia un amigo debe estar por encima de cualquier cálculo.","C":"Rechazar porque comprometer cualquier recurso propio con otra persona supone demasiada dependencia."},"correcta":"A","source_id":"AMPLIACION-20260815-094","modo":"personaje"},{"id":"AMP095","lote":5,"pagina":95,"eneatipo":6,"subtipo":"general","pregunta":"Cuando la Prevencionista cuenta un miedo importante a alguien cercano, ¿qué puede estar ocurriendo además de desahogarse?","opciones":{"A":"Está intentando que el otro se haga cargo del problema por él.","B":"También puede estar observando cómo responde esa persona y si demuestra ser alguien seguro cuando él baja la guardia.","C":"Necesita que el otro confirme que su emoción es única y difícil de comprender."},"correcta":"B","source_id":"AMPLIACION-20260815-095","modo":"personaje"},{"id":"AMP096","lote":5,"pagina":96,"eneatipo":6,"subtipo":"general","pregunta":"A las tres de la mañana suena la alarma de incendios del hotel. Diez minutos después recepción dice que ha sido un fallo técnico. ¿Qué reacción encaja mejor con la Prevencionista?","opciones":{"A":"Olvidarse inmediatamente del asunto porque una autoridad ya ha confirmado que no existe peligro.","B":"Indignarse principalmente porque el hotel no haya cumplido correctamente su protocolo.","C":"Volver a la cama, pero quizá comprobar antes dónde está la salida y dejar a mano lo necesario «por si acaso»."},"correcta":"C","source_id":"AMPLIACION-20260815-096","modo":"personaje"},{"id":"AMP097","lote":5,"pagina":97,"eneatipo":7,"subtipo":"general","pregunta":"Cancelan unas vacaciones que la Ilusionista llevaba meses esperando, pero le ofrecen devolver el dinero o cambiarlo por otro destino. ¿Qué reacción es bastante probable?","opciones":{"A":"Pasar rápidamente de la decepción a fantasear con tres alternativas que podrían ser incluso mejores que el plan original.","B":"Quedarse centrado en que la cancelación demuestra que la empresa no es fiable.","C":"Exigir que se respete el plan inicial porque cambiar lo acordado es inadmisible."},"correcta":"A","source_id":"AMPLIACION-20260815-097","modo":"personaje"},{"id":"AMP098","lote":5,"pagina":98,"eneatipo":7,"subtipo":"general","pregunta":"La pareja de la Ilusionista lleva diez minutos escuchándolo comparar restaurantes y finalmente dice: «Elige uno. No necesitamos doce opciones». ¿Qué puede costarle realmente?","opciones":{"A":"Elegir mal y que la otra persona luego le reproche la decisión.","B":"Cerrar posibilidades cuando todavía existen varias opciones atractivas.","C":"Aceptar que la pareja tenga más autoridad sobre el plan."},"correcta":"B","source_id":"AMPLIACION-20260815-098","modo":"personaje"},{"id":"AMP099","lote":5,"pagina":99,"eneatipo":7,"subtipo":"general","pregunta":"En una reunión familiar surge un problema serio y la conversación se vuelve pesada durante horas. ¿Qué reacción puede aparecer en la Ilusionista?","opciones":{"A":"Mantener la discusión hasta que todo el mundo admita cuál es la solución correcta.","B":"Callarse para que nadie aumente todavía más la tensión.","C":"Introducir humor, nuevas perspectivas o planes de acción para sacar al grupo de un estado emocional que empieza a resultarle asfixiante."},"correcta":"C","source_id":"AMPLIACION-20260815-099","modo":"personaje"},{"id":"AMP100","lote":5,"pagina":100,"eneatipo":7,"subtipo":"general","pregunta":"A la Ilusionista le llegan inesperadamente 500 euros que no esperaba recibir. ¿Qué puede suceder en los primeros cinco minutos?","opciones":{"A":"Su cabeza empieza a convertir ese dinero en experiencias, proyectos o posibilidades antes incluso de decidir si debería guardarlo.","B":"Lo separa automáticamente como fondo de seguridad ante futuros problemas.","C":"Calcula qué compra mejoraría más la imagen que proyecta ante los demás."},"correcta":"A","source_id":"AMPLIACION-20260815-100","modo":"personaje"},{"id":"AMP101","lote":5,"pagina":101,"eneatipo":7,"subtipo":"general","pregunta":"La Ilusionista lleva cuarenta minutos atrapado en una reunión extraordinariamente aburrida. ¿Qué es probable que empiece a hacer mentalmente?","opciones":{"A":"Repasar todo lo que el resto está haciendo incorrectamente.","B":"Crear asociaciones, bromas, ideas paralelas o planes para después con los que mantener su propia estimulación.","C":"Observar en silencio para no gastar más energía de la necesaria."},"correcta":"B","source_id":"AMPLIACION-20260815-101","modo":"personaje"},{"id":"AMP102","lote":5,"pagina":102,"eneatipo":7,"subtipo":"general","pregunta":"Una empresa anuncia: «Durante los próximos seis meses no se podrá cambiar absolutamente nada del proyecto». ¿Qué puede resultarle especialmente difícil a la Ilusionista?","opciones":{"A":"Que un plan tan largo aumente las probabilidades de que algo salga mal.","B":"Que se haya establecido la norma sin seguir un criterio suficientemente justo.","C":"La sensación de horizonte cerrado: no poder introducir alternativas si aparece algo más interesante o inteligente."},"correcta":"C","source_id":"AMPLIACION-20260815-102","modo":"personaje"},{"id":"AMP103","lote":5,"pagina":103,"eneatipo":7,"subtipo":"general","pregunta":"La Ilusionista consigue algo que llevaba meses persiguiendo. Dos días después ya está hablando con entusiasmo de su siguiente idea. ¿Qué explica mejor este fenómeno?","opciones":{"A":"La anticipación y la apertura de posibilidades pueden resultarle más estimulantes que permanecer mucho tiempo disfrutando de algo ya conseguido.","B":"Necesita objetivos constantes para demostrar que sigue siendo una persona valiosa.","C":"Cuando algo deja de ser difícil, sospecha que quizá nunca fue suficientemente seguro."},"correcta":"A","source_id":"AMPLIACION-20260815-103","modo":"personaje"},{"id":"AMP104","lote":5,"pagina":104,"eneatipo":7,"subtipo":"general","pregunta":"Un amigo le dice a la Ilusionista: «Cuando estoy mal me das diez soluciones, pero a veces solo necesito que estés conmigo». ¿Qué puede haber detrás?","opciones":{"A":"Cree que cada problema tiene una única forma correcta de solucionarse.","B":"Generar posibilidades le permite ayudar y, a la vez, evitar quedarse demasiado tiempo frente a un dolor que no puede arreglar.","C":"Le preocupa que el amigo se vuelva demasiado dependiente de él."},"correcta":"B","source_id":"AMPLIACION-20260815-104","modo":"personaje"},{"id":"AMP105","lote":5,"pagina":105,"eneatipo":7,"subtipo":"general","pregunta":"La Ilusionista planifica un viaje de cuatro días y termina reservando ocho actividades, tres restaurantes, una excursión nocturna y «ya veremos si da tiempo a otra cosa». ¿Qué patrón aparece?","opciones":{"A":"La necesidad de controlar cada detalle para evitar errores.","B":"La ansiedad de comprobar previamente que todo el itinerario será seguro.","C":"La tendencia a querer exprimir varias experiencias posibles antes de renunciar a alguna de ellas."},"correcta":"C","source_id":"AMPLIACION-20260815-105","modo":"personaje"},{"id":"AMP106","lote":5,"pagina":106,"eneatipo":7,"subtipo":"general","pregunta":"Un proyecto en el que la Ilusionista había invertido meses fracasa. Esa misma tarde ya propone dos formas de reutilizar lo aprendido en algo nuevo. ¿Qué tiene de doble filo?","opciones":{"A":"Su capacidad de reencuadre es genuinamente útil, pero también puede permitirle saltarse demasiado rápido la frustración o la responsabilidad por lo ocurrido.","B":"Está intentando recuperar cuanto antes el reconocimiento perdido.","C":"Necesita demostrar que el fracaso se debió a una ejecución incorrecta de otros."},"correcta":"A","source_id":"AMPLIACION-20260815-106","modo":"personaje"},{"id":"AMP107","lote":5,"pagina":107,"eneatipo":7,"subtipo":"general","pregunta":"La Ilusionista está muy enamorado, pero una conversación sobre exclusividad y compromisos a largo plazo le genera cierta inquietud. ¿Qué contradicción encaja mejor?","opciones":{"A":"Duda de si la otra persona seguirá siendo fiable con el paso del tiempo.","B":"Puede desear profundamente la relación y, al mismo tiempo, notar la renuncia implícita a futuros caminos posibles.","C":"Le preocupa que la relación no refleje suficientemente quién es de forma auténtica."},"correcta":"B","source_id":"AMPLIACION-20260815-107","modo":"personaje"},{"id":"AMP108","lote":5,"pagina":108,"eneatipo":7,"subtipo":"general","pregunta":"La Ilusionista descubre en redes sociales que varios conocidos han ido a un evento espectacular sin invitarlo. ¿Qué podría dolerle especialmente?","opciones":{"A":"Sentir que esas personas no lo necesitan tanto como él pensaba.","B":"Percibir que otros han recibido un reconocimiento social del que él ha quedado fuera.","C":"Saber que una experiencia interesante estaba ocurriendo y que esa posibilidad se cerró sin que él pudiera elegir."},"correcta":"C","source_id":"AMPLIACION-20260815-108","modo":"personaje"},{"id":"AMP109","lote":5,"pagina":109,"eneatipo":7,"subtipo":"general","pregunta":"Llueve todo el día, se cancela cualquier plan y la Ilusionista tiene que quedarse en casa. ¿Qué respuesta encaja mejor?","opciones":{"A":"Inventarse algo: una receta rara, un juego, una reforma improvisada o un futuro viaje, convirtiendo el encierro en una fuente nueva de estímulos.","B":"Agradecer que por fin nadie pueda pedirle absolutamente nada.","C":"Aprovechar para terminar primero todas las obligaciones pendientes antes de permitirse divertirse."},"correcta":"A","source_id":"AMPLIACION-20260815-109","modo":"personaje"},{"id":"AMP110","lote":5,"pagina":110,"eneatipo":7,"subtipo":"general","pregunta":"La Ilusionista prometió dedicar la noche a terminar un trámite pesado. Una hora antes, un amigo consigue entradas inesperadas para un concierto. ¿Qué diálogo interno puede aparecer?","opciones":{"A":"«¿Qué opción demostrará mejor que soy una persona responsable?»","B":"«Puedo hacer el trámite mañana; esta oportunidad quizá no vuelva a aparecer».","C":"«¿Y si voy y mañana ocurre algo que me impide terminarlo?»."},"correcta":"B","source_id":"AMPLIACION-20260815-110","modo":"personaje"},{"id":"AMP111","lote":5,"pagina":111,"eneatipo":7,"subtipo":"general","pregunta":"Después de una ruptura, un amigo pide a la Ilusionista: «Quédate aquí conmigo un rato. No quiero hablar ni hacer nada». ¿Qué puede ser especialmente difícil?","opciones":{"A":"No saber qué papel espera exactamente el amigo que desempeñe.","B":"Sentirse inútil porque no puede demostrarle cuánto le importa.","C":"Permanecer voluntariamente junto a una experiencia dolorosa que no puede transformar en actividad, solución o posibilidad futura."},"correcta":"C","source_id":"AMPLIACION-20260815-111","modo":"personaje"},{"id":"AMP112","lote":5,"pagina":112,"eneatipo":7,"subtipo":"general","pregunta":"Un ascensor se queda detenido veinticinco minutos con la Ilusionista y cuatro desconocidos dentro. ¿Qué comportamiento sería muy coherente?","opciones":{"A":"Empezar una conversación, inventar un juego o convertir la situación absurda en algo con lo que entretenerse mientras llega ayuda.","B":"Revisar repetidamente todos los escenarios de avería posibles.","C":"Exigir inmediatamente saber quién es responsable de haber permitido el fallo."},"correcta":"A","source_id":"AMPLIACION-20260815-112","modo":"personaje"},{"id":"AMP113","lote":5,"pagina":113,"eneatipo":8,"subtipo":"general","pregunta":"Un compañero presenta como propia una idea que el Protector había desarrollado con él. ¿Qué puede activar especialmente su reacción?","opciones":{"A":"Que el mérito oficial no refleje de forma exacta quién hizo cada parte.","B":"La sensación de que alguien está intentando aprovecharse de él y cruzar un límite sin consecuencias.","C":"El miedo a que el jefe empiece a considerarlo menos competente."},"correcta":"B","source_id":"AMPLIACION-20260815-113","modo":"personaje"},{"id":"AMP114","lote":5,"pagina":114,"eneatipo":8,"subtipo":"general","pregunta":"La pareja del Protector compra algo importante para ambos sin consultarlo y dice: «Sabía que ibas a estar de acuerdo». Aunque al Protector le guste la compra, ¿qué puede enfadarle?","opciones":{"A":"Que no se haya comparado suficientemente bien si era la mejor opción.","B":"Que se haya roto una forma correcta de tomar decisiones en pareja.","C":"Que alguien haya decidido en su nombre y haya dado por hecho que podía disponer de su capacidad de elección."},"correcta":"C","source_id":"AMPLIACION-20260815-114","modo":"personaje"},{"id":"AMP115","lote":5,"pagina":115,"eneatipo":8,"subtipo":"general","pregunta":"Un jefe le pide al Protector algo perfectamente razonable, pero termina la frase con: «Y lo vas a hacer porque aquí mando yo». ¿Qué cambia?","opciones":{"A":"La forma coercitiva puede activar una resistencia mucho mayor que la petición original.","B":"El Protector obedecerá si entiende que la petición es objetivamente correcta.","C":"El Protector empezará principalmente a preguntarse si desobedecer pondría en riesgo su puesto."},"correcta":"A","source_id":"AMPLIACION-20260815-115","modo":"personaje"},{"id":"AMP116","lote":5,"pagina":116,"eneatipo":8,"subtipo":"general","pregunta":"Un vendedor intenta aprovecharse claramente de un familiar mayor del Protector utilizando presión y letra pequeña. ¿Qué reacción es probable?","opciones":{"A":"Revisar primero todo el contrato para demostrar técnicamente dónde está el error.","B":"Intervenir de forma muy directa, especialmente porque percibe que alguien con ventaja está intentando abusar de alguien más vulnerable.","C":"Recomendar al familiar que aprenda a defenderse solo para no generar dependencia."},"correcta":"B","source_id":"AMPLIACION-20260815-116","modo":"personaje"},{"id":"AMP117","lote":5,"pagina":117,"eneatipo":8,"subtipo":"general","pregunta":"Después de una semana muy dura, la pareja del Protector le dice: «Aquí no tienes que ser fuerte. Puedes derrumbarte». ¿Qué puede resultarle incómodo?","opciones":{"A":"No saber exactamente qué espera la pareja que haga después de derrumbarse.","B":"Temer que mostrar emociones altere la armonía de la relación.","C":"Sentirse completamente expuesto y dependiente puede resultar más amenazante que seguir enfrentándose al problema."},"correcta":"C","source_id":"AMPLIACION-20260815-117","modo":"personaje"},{"id":"AMP118","lote":5,"pagina":118,"eneatipo":8,"subtipo":"general","pregunta":"Un socio propone al Protector utilizar una cuenta común para todos los gastos sin límites claros porque «entre nosotros hay confianza». ¿Qué es probable?","opciones":{"A":"Preferir reglas que le permitan saber y decidir cómo se utilizan recursos que afectan directamente a su autonomía.","B":"Aceptar si eso hace que la relación con el socio sea más estrecha.","C":"Rechazar principalmente porque compartir recursos supone un gasto energético excesivo."},"correcta":"A","source_id":"AMPLIACION-20260815-118","modo":"personaje"},{"id":"AMP119","lote":5,"pagina":119,"eneatipo":8,"subtipo":"general","pregunta":"Un amigo está molesto con el Protector pero, en lugar de decírselo, lleva días lanzando indirectas. ¿Qué puede irritar especialmente al Protector?","opciones":{"A":"No poder saber con seguridad qué consecuencias tendrá el conflicto.","B":"Que el otro evite poner las cartas sobre la mesa y trate de influir desde la sombra en lugar de enfrentarlo directamente.","C":"Que la discusión esté rompiendo innecesariamente la armonía del grupo."},"correcta":"B","source_id":"AMPLIACION-20260815-119","modo":"personaje"},{"id":"AMP120","lote":5,"pagina":120,"eneatipo":8,"subtipo":"general","pregunta":"Un rival vence limpiamente al Protector en una competición muy dura y no presume después. ¿Qué reacción no sería extraña?","opciones":{"A":"Perder automáticamente cualquier interés porque quedar segundo demuestra debilidad.","B":"Buscar una excusa técnica que invalide la derrota.","C":"Aumentar su respeto por esa persona precisamente porque ha demostrado fuerza de frente y sin jugar sucio."},"correcta":"C","source_id":"AMPLIACION-20260815-120","modo":"personaje"},{"id":"AMP121","lote":5,"pagina":121,"eneatipo":8,"subtipo":"general","pregunta":"El propietario de la vivienda del Protector le comunica: «Mañana entraré a revisar el piso; ya he decidido la hora». ¿Qué puede encender el conflicto incluso aunque legalmente pudiera realizar una inspección?","opciones":{"A":"Que se presente el acceso a su espacio como una imposición en la que él no tiene voz.","B":"Que la inspección altere un plan previamente organizado.","C":"Que no haya suficiente información sobre todo lo que podría ocurrir durante la visita."},"correcta":"A","source_id":"AMPLIACION-20260815-121","modo":"personaje"},{"id":"AMP122","lote":5,"pagina":122,"eneatipo":8,"subtipo":"general","pregunta":"Un amigo dice al Protector: «No te conté mi problema porque sabía que ibas a intentar solucionarlo tú». ¿Qué punto ciego puede haber?","opciones":{"A":"El Protector necesita que los demás reconozcan constantemente todo lo que hace por ellos.","B":"Puede vivir su intervención como protección y no percibir que su intensidad también puede quitar al otro capacidad de decidir por sí mismo.","C":"Ayuda para no tener que pensar en sus propios problemas."},"correcta":"B","source_id":"AMPLIACION-20260815-122","modo":"personaje"},{"id":"AMP123","lote":5,"pagina":123,"eneatipo":8,"subtipo":"general","pregunta":"En mitad de una crisis laboral nadie sabe qué hacer y todos discuten. ¿Qué respuesta es bastante probable en el Protector?","opciones":{"A":"Esperar a que una figura de autoridad legítima marque un procedimiento.","B":"Dedicar primero tiempo a escuchar todas las perspectivas para no generar ninguna fricción.","C":"Tomar una decisión, repartir tareas y empujar al grupo hacia la acción, aun a riesgo de atropellar algunas opiniones."},"correcta":"C","source_id":"AMPLIACION-20260815-123","modo":"personaje"},{"id":"AMP124","lote":5,"pagina":124,"eneatipo":8,"subtipo":"general","pregunta":"Una nueva norma perjudica claramente a empleados con menos poder y nadie quiere cuestionarla porque viene de dirección. ¿Qué reacción encaja mejor con el Protector?","opciones":{"A":"Puede desafiarla abiertamente si la vive como un abuso, aunque enfrentarse a dirección tenga consecuencias.","B":"Intentará modificarla solo a través de los canales establecidos porque saltárselos sería incorrecto.","C":"Preferirá esperar hasta conocer exactamente qué postura apoya la mayoría del equipo."},"correcta":"A","source_id":"AMPLIACION-20260815-124","modo":"personaje"},{"id":"AMP125","lote":5,"pagina":125,"eneatipo":8,"subtipo":"general","pregunta":"La pareja del Protector confiesa que lleva meses ocultándole un problema «para que no te preocuparas». ¿Qué puede doler más allá del problema en sí?","opciones":{"A":"Que el secreto demuestre que la relación no era tan especial como él creía.","B":"Sentir que le han dejado fuera de la realidad y han decidido por él qué podía o no podía afrontar.","C":"No haber detectado antes las señales que indicaban que algo iba mal."},"correcta":"B","source_id":"AMPLIACION-20260815-125","modo":"personaje"},{"id":"AMP126","lote":5,"pagina":126,"eneatipo":8,"subtipo":"general","pregunta":"El Protector pasa una semana en un retiro en el que el programa consiste básicamente en silencio, paseos lentos y no hacer nada exigente. ¿Qué puede aparecer?","opciones":{"A":"Culpa por no estar utilizando el tiempo de forma productiva.","B":"Miedo a que tanta inactividad le impida estar preparado ante posibles problemas.","C":"Inquietud o búsqueda de algo más intenso porque un nivel tan bajo de activación puede resultarle apagado."},"correcta":"C","source_id":"AMPLIACION-20260815-126","modo":"personaje"},{"id":"AMP127","lote":5,"pagina":127,"eneatipo":8,"subtipo":"general","pregunta":"Un negocio del Protector se viene abajo de manera inesperada. ¿Cuál puede ser su primera estrategia frente al golpe?","opciones":{"A":"Volver rápidamente a la acción, recuperar control sobre lo que sí puede hacer y posponer el contacto con la sensación de impotencia.","B":"Compararse con quienes han conseguido mantener sus empresas y sentirse fundamentalmente inferior.","C":"Pedir varias opiniones antes de decidir si es seguro volver a intentarlo."},"correcta":"A","source_id":"AMPLIACION-20260815-127","modo":"personaje"},{"id":"AMP128","lote":5,"pagina":128,"eneatipo":8,"subtipo":"general","pregunta":"Durante un karaoke, el presentador empieza a ridiculizar a un amigo tímido del Protector porque canta fatal. El amigo intenta restarle importancia. ¿Qué es muy posible que haga el Protector?","opciones":{"A":"Dejarlo pasar para no aumentar una situación que ya es incómoda.","B":"Cortar al presentador de forma bastante más contundente de lo que probablemente requería la situación.","C":"Esperar a comprobar primero si el amigo quiere realmente ser defendido."},"correcta":"B","source_id":"AMPLIACION-20260815-128","modo":"personaje"},{"id":"AMP129","lote":5,"pagina":129,"eneatipo":9,"subtipo":"general","pregunta":"Una pareja pregunta a la Imperturbable: «Podemos mudarnos a la costa o quedarnos aquí. ¿Qué quieres tú?». Su pareja tiene clarísima su preferencia. ¿Qué dificultad puede aparecer?","opciones":{"A":"Temer elegir la opción con más riesgos económicos.","B":"Querer analizar cuál sería objetivamente la decisión más correcta.","C":"Tener problemas para localizar su propia preferencia cuando la del otro ocupa mucho espacio."},"correcta":"C","source_id":"AMPLIACION-20260815-129","modo":"personaje"},{"id":"AMP130","lote":5,"pagina":130,"eneatipo":9,"subtipo":"general","pregunta":"La Imperturbable tiene diez pequeñas tareas fáciles y una conversación incómoda que necesita mantener cuanto antes. ¿Qué secuencia resulta bastante probable?","opciones":{"A":"Resolver primero varias tareas de baja fricción y conseguir así aplazar un poco más la conversación que le activa.","B":"Tener la conversación inmediatamente para eliminar cualquier asunto pendiente.","C":"Analizarla durante horas para preparar todos los posibles argumentos del otro."},"correcta":"A","source_id":"AMPLIACION-20260815-130","modo":"personaje"},{"id":"AMP131","lote":5,"pagina":131,"eneatipo":9,"subtipo":"general","pregunta":"Un amigo pide un favor de última hora que choca con un plan que la Imperturbable había hecho para sí mismo. ¿Qué respuesta automática puede aparecer?","opciones":{"A":"Negarse de inmediato para proteger su espacio y sus recursos.","B":"Decir que sí casi por inercia y descubrir después, quizá mientras lo hace con una lentitud sospechosa, que en realidad no quería.","C":"Negociar el favor de forma que quede claro qué recibirá a cambio."},"correcta":"B","source_id":"AMPLIACION-20260815-131","modo":"personaje"},{"id":"AMP132","lote":5,"pagina":132,"eneatipo":9,"subtipo":"general","pregunta":"Un jefe da instrucciones de forma agresiva y contradictoria a la Imperturbable. ¿Qué respuesta puede aparecer en lugar de una confrontación abierta?","opciones":{"A":"Corregirlo hasta que admita cuál es la instrucción correcta.","B":"Desafiarlo inmediatamente para impedir que vuelva a hablarle así.","C":"Asentir en el momento y terminar haciendo después aquello que le resulte menos disruptivo o más llevadero."},"correcta":"C","source_id":"AMPLIACION-20260815-132","modo":"personaje"},{"id":"AMP133","lote":5,"pagina":133,"eneatipo":9,"subtipo":"general","pregunta":"Durante unas vacaciones cinco amigos quieren hacer planes distintos y empieza una discusión absurda. ¿Qué papel puede asumir espontáneamente la Imperturbable?","opciones":{"A":"Buscar una combinación en la que todo el mundo ceda un poco, aunque su propia preferencia termine siendo la menos representada.","B":"Defender con fuerza su plan para que el grupo salga por fin de la indecisión.","C":"Calcular qué alternativa tiene menos probabilidades de generar problemas imprevistos."},"correcta":"A","source_id":"AMPLIACION-20260815-133","modo":"personaje"},{"id":"AMP134","lote":5,"pagina":134,"eneatipo":9,"subtipo":"general","pregunta":"A la Imperturbable competente le ofrecen liderar un proyecto importante y su primera respuesta es «No sé si yo soy la persona adecuada». ¿Qué puede haber debajo además de inseguridad?","opciones":{"A":"Liderar lo obligaría a ser visible y demostrar constantemente su valor.","B":"El puesto exige definir prioridades, ocupar espacio y provocar desacuerdos que normalmente puede evitar desde una posición secundaria.","C":"Necesitaría adquirir demasiada información antes de sentirse preparado."},"correcta":"B","source_id":"AMPLIACION-20260815-134","modo":"personaje"},{"id":"AMP135","lote":5,"pagina":135,"eneatipo":9,"subtipo":"general","pregunta":"La Imperturbable tiene un conflicto importante sin resolver con su pareja. Esa noche se pone una serie, recoge la cocina y parece sorprendentemente tranquilo. ¿Qué podría estar ocurriendo?","opciones":{"A":"Ya ha procesado el conflicto y simplemente ha decidido que no merece atención.","B":"Está castigando deliberadamente a la pareja mediante indiferencia.","C":"Puede estar volviendo a rutinas conocidas para amortiguar la activación y posponer el momento de entrar realmente en el conflicto."},"correcta":"C","source_id":"AMPLIACION-20260815-135","modo":"personaje"},{"id":"AMP136","lote":5,"pagina":136,"eneatipo":9,"subtipo":"general","pregunta":"El banco pide a la Imperturbable que complete un trámite aburrido pero importante. Tiene un mes entero de plazo y tarda veinte minutos. ¿Qué patrón podría aparecer?","opciones":{"A":"Posponerlo durante semanas porque no genera suficiente urgencia externa como para vencer la resistencia inicial a ponerse con ello.","B":"Hacerlo el primer día porque dejar cualquier obligación pendiente produce demasiado malestar.","C":"Investigar antes todas las consecuencias posibles de completarlo incorrectamente."},"correcta":"A","source_id":"AMPLIACION-20260815-136","modo":"personaje"},{"id":"AMP137","lote":5,"pagina":137,"eneatipo":9,"subtipo":"general","pregunta":"Un amigo muy activo propone constantemente planes y la Imperturbable suele apuntarse a casi todos. ¿Qué explicación puede ser más fina que «a la Imperturbable le gusta hacer de todo»?","opciones":{"A":"Necesita estar rodeado de gente para sentirse importante dentro del grupo.","B":"Puede resultarle más fácil engancharse al impulso y las prioridades de otra persona que generar y defender continuamente las suyas.","C":"Acepta tantos planes para no perder ninguna oportunidad estimulante."},"correcta":"B","source_id":"AMPLIACION-20260815-137","modo":"personaje"},{"id":"AMP138","lote":5,"pagina":138,"eneatipo":9,"subtipo":"general","pregunta":"Después de una discusión, alguien pregunta a la Imperturbable: «¿Estás enfadado conmigo?». Él responde sinceramente: «No». Dos horas después hace todo con una lentitud desesperante. ¿Qué puede estar ocurriendo?","opciones":{"A":"Está intentando castigar conscientemente al otro sin reconocerlo.","B":"Ha decidido que enfadarse sería incorrecto y está reprimiendo la emoción por disciplina.","C":"Puede no tener acceso inmediato a su propio enfado y expresarlo indirectamente mediante resistencia, demora o desconexión."},"correcta":"C","source_id":"AMPLIACION-20260815-138","modo":"personaje"},{"id":"AMP139","lote":5,"pagina":139,"eneatipo":9,"subtipo":"general","pregunta":"Un plan social que obligaba a la Imperturbable a arreglarse, conducir una hora y conocer gente nueva se cancela en el último momento. Le apetecía ir. ¿Qué reacción también podría aparecer?","opciones":{"A":"Cierto alivio porque ya no tiene que movilizarse y puede permanecer en su estado conocido.","B":"Frustración intensa porque acaba de perder una posibilidad que quizá no vuelva a existir.","C":"Preocupación por si la cancelación esconde algún problema entre los asistentes."},"correcta":"A","source_id":"AMPLIACION-20260815-139","modo":"personaje"},{"id":"AMP140","lote":5,"pagina":140,"eneatipo":9,"subtipo":"general","pregunta":"Un desconocido escribe en redes algo con lo que la Imperturbable está totalmente en desacuerdo. Empieza a responder, pero termina borrando el comentario. ¿Qué pensamiento encaja mejor?","opciones":{"A":"«No tengo suficientes datos para defender esta postura todavía».","B":"«Podría discutirlo, pero no sé si quiero meterme en una pelea que no va a cambiar nada».","C":"«Si publico esto, quizá dé una imagen menos atractiva de mí»."},"correcta":"B","source_id":"AMPLIACION-20260815-140","modo":"personaje"},{"id":"AMP141","lote":5,"pagina":141,"eneatipo":9,"subtipo":"general","pregunta":"Cuatro personas empiezan juntas un proyecto sin fechas, roles ni una persona que coordine. ¿Qué riesgo particular existe para la Imperturbable?","opciones":{"A":"Intentar corregir constantemente el trabajo de todos y retrasar el resultado.","B":"Acaparar demasiadas funciones para demostrar que el proyecto lo necesita.","C":"Quedarse en una especie de espera difusa hasta que una estructura o la energía de otra persona le proporcione impulso."},"correcta":"C","source_id":"AMPLIACION-20260815-141","modo":"personaje"},{"id":"AMP142","lote":5,"pagina":142,"eneatipo":9,"subtipo":"general","pregunta":"Dos familiares enfrentados piden a la Imperturbable que diga claramente quién tiene razón. ¿Qué puede resultarle difícil?","opciones":{"A":"Comprender tan bien las razones de ambos que su propia posición termine desapareciendo entre todos los matices.","B":"Decidir cuál de las dos versiones dispone de información suficientemente fiable.","C":"Defender una postura que no se corresponda con las normas correctas de la familia."},"correcta":"A","source_id":"AMPLIACION-20260815-142","modo":"personaje"},{"id":"AMP143","lote":5,"pagina":143,"eneatipo":9,"subtipo":"general","pregunta":"Durante una pequeña emergencia todos están nerviosos y la Imperturbable que llevaba toda la tarde apático empieza a resolver cosas con sorprendente calma. ¿Cómo se explica?","opciones":{"A":"Necesita que haya público para activar su capacidad de actuar.","B":"Una demanda externa concreta puede movilizarlo mucho mejor que aquellas prioridades propias que no tienen urgencia ni presión inmediata.","C":"Los problemas graves le resultan más estimulantes que una vida tranquila."},"correcta":"B","source_id":"AMPLIACION-20260815-143","modo":"personaje"},{"id":"AMP144","lote":5,"pagina":144,"eneatipo":9,"subtipo":"general","pregunta":"En un restaurante traen a la Imperturbable un plato equivocado. Lo devuelve amablemente. Diez minutos después vuelven a traerle otro distinto al que pidió, pero este también le gusta. ¿Qué podría hacer?","opciones":{"A":"Devolverlo otra vez porque aceptar un error solo garantiza que vuelva a repetirse.","B":"Pedir hablar con el encargado para evitar que el camarero siga tomando decisiones por él.","C":"Comérselo pensando «bah, este también está bien» antes que generar una tercera ronda de interacción por algo que puede tolerar perfectamente."},"correcta":"C","source_id":"AMPLIACION-20260815-144","modo":"personaje"}];
